    ? { state: previewOwn.state ?? null, url: previewOwn.url ?? null, bundlePath: previewOwn.bundlePath ?? null, indexSha256: previewOwn.indexSha256 ?? null, bundleSha256: previewOwn.bundleSha256 ?? null }
