  const walkTo = async (label, target, { arrive = 1.0, budgetMs = BUDGET.leg, sample = null } = {}) => {
    const t = Date.now(); const start = poseOf(await cgSnap(page)); let last = start; let stallMs = 0; let travelled = 0;
